local M = {}

-- ┌──────────────────────────────────────┐
-- │ Flake palette colorscheme            │
-- └──────────────────────────────────────┘
-- `flake_palette` is generated by modules/home/neovim/default.nix from
-- lib/themes.nix; `background` selects its light or dark variant.
local group_modules = {
	"plugins.theme.flake.groups.editor",
	"plugins.theme.flake.groups.syntax",
	"plugins.theme.flake.groups.treesitter",
	"plugins.theme.flake.groups.lsp",
	"plugins.theme.flake.groups.plugins",
	"plugins.theme.flake.groups.vcs",
}

--- Resolved semantic colours for a variant, or nil without the generated palette.
---@param variant? "light"|"dark"
function M.colors(variant)
	local ok, palette = pcall(require, "flake_palette")
	if not ok then
		return nil
	end
	variant = variant or vim.o.background
	return require("plugins.theme.flake.palette").build(palette[variant], palette.terminal[variant])
end

--- Every highlight group the colorscheme defines; a string value is a link.
function M.groups(c)
	local groups = {}
	for _, name in ipairs(group_modules) do
		for group, spec in pairs(require(name).get(c)) do
			groups[group] = spec
		end
	end
	return groups
end

function M.load()
	local c = M.colors()
	if not c then
		vim.notify("flake colorscheme: flake_palette is not on the runtimepath", vim.log.levels.WARN)
		vim.cmd.colorscheme("default")
		return
	end

	if vim.g.colors_name then
		vim.cmd.highlight("clear")
	end
	vim.g.colors_name = "flake"

	for group, spec in pairs(M.groups(c)) do
		if type(spec) == "string" then
			spec = { link = spec }
		end
		vim.api.nvim_set_hl(0, group, spec)
	end

	for index, color in ipairs(c.terminal) do
		vim.g["terminal_color_" .. (index - 1)] = color
	end
end

return M
